include { BOWTIE2_ALIGN                            } from 'nf-core/bowtie2/align'
include { BOWTIE2_ALIGN as BOWTIE2_ALIGN_PE        } from 'nf-core/bowtie2/align'
include { BOWTIE2_BUILD                            } from 'nf-core/bowtie2/build'
include { RIBODETECTOR                             } from 'nf-core/ribodetector'
include { SAMTOOLS_FASTQ as SAMTOOLS_FASTQ_BOWTIE2 } from 'nf-core/samtools/fastq'
include { SAMTOOLS_VIEW as SAMTOOLS_VIEW_BOWTIE2   } from 'nf-core/samtools/view'
include { SEQKIT_REPLACE                           } from 'nf-core/seqkit/replace'
include { SEQKIT_REPLACE as SEQKIT_REPLACE_U2T     } from 'nf-core/seqkit/replace'
include { SEQKIT_STATS                             } from 'nf-core/seqkit/stats'
include { SORTMERNA                                } from 'nf-core/sortmerna'
include { SORTMERNA as SORTMERNA_INDEX             } from 'nf-core/sortmerna'

//
// Function that parses seqkit stats TSV output to extract the mean read length
// for use with RiboDetector's -l parameter
//
def getReadLengthFromSeqkitStats(stats_file) {
    def lines = stats_file.text.readLines()
    if (lines.size() < 2) {
        return 100 // Default fallback
    }

    def header = lines[0].split('\t')
    def avgLenIdx = header.findIndexOf { col -> col == 'avg_len' }
    if (avgLenIdx < 0) {
        return 100 // Default fallback if column not found
    }

    // Calculate mean avg_len across all files in the stats output
    def avgLens = lines[1..-1].collect { line -> line.split('\t')[avgLenIdx] as float }
    def meanAvgLen = avgLens.sum() / avgLens.size()

    return Math.round(meanAvgLen) as int
}

workflow FASTQ_REMOVE_RRNA {
    take:
    ch_reads // channel: [ val(meta), [ reads ] ]
    ch_rrna_fastas // channel: one or more fasta files containing rrna sequences
    ch_sortmerna_index // channel: /path/to/sortmerna/index/ (optional)
    ch_bowtie2_index // channel: /path/to/bowtie2/index/ (optional)
    ribo_removal_tool // string (enum): 'sortmerna', 'ribodetector', or 'bowtie2'
    make_sortmerna_index // boolean: Whether to create a sortmerna index before running sortmerna
    make_bowtie2_index // boolean: Whether to create a bowtie2 index before running bowtie2

    main:

    ch_multiqc_files = channel.empty()
    ch_filtered_reads = ch_reads

    // Individual output channels for workflow outputs
    ch_sortmerna_log = channel.empty()
    ch_ribodetector_log = channel.empty()
    ch_seqkit_stats = channel.empty()
    ch_bowtie2_log = channel.empty()
    ch_bowtie2_index_out = channel.empty()
    ch_seqkit_prefixed = channel.empty()
    ch_seqkit_converted = channel.empty()

    if (ribo_removal_tool == 'sortmerna') {
        ch_sortmerna_fastas = ch_rrna_fastas
            .collect()
            .map { fastas -> [[id: 'rrna_refs'], fastas] }

        if (make_sortmerna_index) {
            SORTMERNA_INDEX(
                [[], []],
                ch_sortmerna_fastas,
                [[], []],
            )
            ch_sortmerna_index = SORTMERNA_INDEX.out.index
        }

        SORTMERNA(
            ch_filtered_reads,
            ch_sortmerna_fastas,
            ch_sortmerna_index,
        )

        ch_filtered_reads = SORTMERNA.out.reads
        ch_sortmerna_log = SORTMERNA.out.log
        ch_multiqc_files = ch_multiqc_files.mix(SORTMERNA.out.log)
    }
    else if (ribo_removal_tool == 'ribodetector') {
        // Run seqkit stats to determine average read length
        SEQKIT_STATS(ch_filtered_reads)

        ch_seqkit_stats = SEQKIT_STATS.out.stats
        ch_multiqc_files = ch_multiqc_files.mix(SEQKIT_STATS.out.stats)

        // Join stats with reads and calculate read length for RiboDetector
        ch_filtered_reads
            .join(SEQKIT_STATS.out.stats)
            .multiMap { meta, reads, stats ->
                def readLength = getReadLengthFromSeqkitStats(stats)
                reads: [meta, reads]
                length: readLength
            }
            .set { ch_reads_with_length }

        RIBODETECTOR(
            ch_reads_with_length.reads,
            ch_reads_with_length.length,
        )

        ch_filtered_reads = RIBODETECTOR.out.fastq
        ch_ribodetector_log = RIBODETECTOR.out.log
        ch_multiqc_files = ch_multiqc_files.mix(RIBODETECTOR.out.log)
    }
    else if (ribo_removal_tool == 'bowtie2') {
        if (make_bowtie2_index) {
            // Process each rRNA file to add unique prefixes and convert U to T
            // This prevents duplicate sequence IDs in SAM header when combining databases
            ch_rrna_fastas
                .map { fasta_file -> [[id: fasta_file.baseName], fasta_file] }
                .set { ch_rrna_with_meta }

            // Step 1: Add filename prefixes to sequence headers
            SEQKIT_REPLACE(ch_rrna_with_meta, '')
            ch_seqkit_prefixed = SEQKIT_REPLACE.out.fastx

            // Step 2: Convert U to T in sequences (RNA to DNA)
            SEQKIT_REPLACE.out.fastx
                .map { meta, fasta_file -> [[id: "${meta.id}_dna"], fasta_file] }
                .set { ch_prefixed_fastas }

            SEQKIT_REPLACE_U2T(ch_prefixed_fastas, '')
            ch_seqkit_converted = SEQKIT_REPLACE_U2T.out.fastx

            // Collect processed files (already prefixed and U->T converted)
            SEQKIT_REPLACE_U2T.out.fastx
                .map { _meta, fasta_file -> fasta_file }
                .collectFile(name: 'rrna_combined_dna.fasta', newLine: true)
                .map { fasta_file -> [[id: 'rrna_refs'], fasta_file] }
                .set { ch_combined_fasta }

            BOWTIE2_BUILD(ch_combined_fasta)
            ch_bowtie2_index = BOWTIE2_BUILD.out.index.first()
            ch_bowtie2_index_out = BOWTIE2_BUILD.out.index
        }

        // Branch reads by single-end vs paired-end for different filtering strategies
        ch_filtered_reads
            .branch { meta, _reads ->
                single_end: meta.single_end
                paired_end: !meta.single_end
            }
            .set { ch_reads_for_bowtie2 }

        // For single-end reads: bowtie2's --un-gz works correctly
        // save_unaligned=true outputs unmapped reads directly
        BOWTIE2_ALIGN(
            ch_reads_for_bowtie2.single_end,
            ch_bowtie2_index,
            [[], []], // No reference fasta needed
            true,     // save_unaligned - for single-end this works correctly
            false,    // sort_bam - not needed
        )

        ch_bowtie2_log = BOWTIE2_ALIGN.out.log
        ch_multiqc_files = ch_multiqc_files.mix(BOWTIE2_ALIGN.out.log)

        // For paired-end reads: bowtie2's --un-conc-gz outputs pairs that didn't
        // align concordantly, which INCLUDES pairs where one mate aligned.
        // We need to filter via samtools to get pairs where BOTH mates are unmapped.
        BOWTIE2_ALIGN_PE(
            ch_reads_for_bowtie2.paired_end,
            ch_bowtie2_index,
            [[], []], // No reference fasta needed for BAM output
            false,    // save_unaligned - we'll extract from BAM instead
            false,    // sort_bam - not needed
        )

        ch_bowtie2_log = ch_bowtie2_log.mix(BOWTIE2_ALIGN_PE.out.log)
        ch_multiqc_files = ch_multiqc_files.mix(BOWTIE2_ALIGN_PE.out.log)

        // Filter BAM for read pairs where BOTH mates are unmapped (flag 12 = 4 + 8)
        // This removes any pair where at least one mate aligned to rRNA
        SAMTOOLS_VIEW_BOWTIE2(
            BOWTIE2_ALIGN_PE.out.bam.map { meta, bam_file -> [meta, bam_file, []] },
            [[], [], []], // No reference fasta
            [[], []],     // No qname file
            [[], []],     // No bed file
            []            // No index format
        )
        // Note: samtools/view versions collected via topic

        // Convert filtered BAM back to paired FASTQ
        SAMTOOLS_FASTQ_BOWTIE2(
            SAMTOOLS_VIEW_BOWTIE2.out.bam,
            false, // not interleaved
        )

        // Combine single-end and paired-end results
        BOWTIE2_ALIGN.out.fastq
            .mix(SAMTOOLS_FASTQ_BOWTIE2.out.fastq)
            .set { ch_filtered_reads }
    }

    emit:
    reads            = ch_filtered_reads // channel: [ val(meta), [ reads ] ]
    multiqc_files    = ch_multiqc_files // channel: [ val(meta), [ log files ] ]
    sortmerna_log    = ch_sortmerna_log // channel: [ val(meta), [ log ] ]
    ribodetector_log = ch_ribodetector_log // channel: [ val(meta), [ log ] ]
    seqkit_stats     = ch_seqkit_stats // channel: [ val(meta), [ stats ] ]
    bowtie2_log      = ch_bowtie2_log // channel: [ val(meta), [ log ] ]
    bowtie2_index    = ch_bowtie2_index_out // channel: [ val(meta), [ index ] ]
    seqkit_prefixed  = ch_seqkit_prefixed // channel: [ val(meta), [ fasta ] ]
    seqkit_converted = ch_seqkit_converted // channel: [ val(meta), [ fasta ] ]
}

nextflow_workflow {

    name "Test Subworkflow FASTQ_REMOVE_RRNA"
    script "../main.nf"
    workflow "FASTQ_REMOVE_RRNA"
    config "./nextflow.config"

    tag "bowtie2"
    tag "bowtie2/align"
    tag "bowtie2/build"
    tag "cat"
    tag "cat/fastq"
    tag "ribodetector"
    tag "samtools"
    tag "samtools/fastq"
    tag "samtools/view"
    tag "seqkit"
    tag "seqkit/replace"
    tag "seqkit/stats"
    tag "sortmerna"
    tag "subworkflows"
    tag "subworkflows/fastq_remove_rrna"
    tag "subworkflows_nfcore"

    // Global setup: Create test data with synthetic rRNA reads using CAT_FASTQ
    // The rRNA reads (from generic/fastq/) are 5.8S rRNA sequences that will be detected
    // by SortMeRNA (alignment-based, 100% detection), RiboDetector (ML-based, ~70% detection),
    // and Bowtie2 (alignment-based)
    setup {
        run("CAT_FASTQ") {
            script "../../../../modules/nf-core/cat/fastq/main.nf"
            process {
                """
                // CAT_FASTQ input: alternating R1/R2 files [r1_a, r2_a, r1_b, r2_b, ...]
                input[0] = Channel.of([
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_2.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'generic/fastq/rrna_reads_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'generic/fastq/rrna_reads_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                """
            }
        }
    }

    test("homo_sapiens paired-end [fastq] sortmerna") {

        when {
            workflow {
                """
                input[0] = CAT_FASTQ.out.reads                                    // ch_reads
                input[1] = Channel.of(file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/rfam-5.8s-database-id98.fasta', checkIfExists: true)) // ch_rrna_fastas
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'sortmerna'                                            // ribo_removal_tool
                input[5] = true                                                   // make_sortmerna_index
                input[6] = false                                                  // make_bowtie2_index
                """
            }
        }

        then {
            def pelines1 = path(workflow.out.reads[0][1][0]).linesGzip
            def pelines2 = path(workflow.out.reads[0][1][1]).linesGzip

            // Parse sortmerna log for rRNA detection stats
            def sortmernaLog = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.sortmerna.log') }?.getAt(1))
                .getText()
            def sortmernaRrnaMatch = (sortmernaLog =~ /Total reads passing E-value threshold = (\d+)/)
            def sortmernaRrnaCount = sortmernaRrnaMatch ? sortmernaRrnaMatch[0][1].toInteger() : -1

            // Input: 4159 original + 10 synthetic rRNA = 4169 read pairs
            // SortMeRNA removes all 10 synthetic rRNA pairs (20 individual reads), leaving 4159 pairs
            assertAll(
                { assert workflow.success },
                { assert pelines1.size() == 16636 },  // 4159 pairs × 4 lines/read
                { assert pelines2.size() == 16636 },
                { assert sortmernaRrnaCount == 20 },  // 10 pairs = 20 individual reads (100% detection)
                { assert snapshot(
                    pelines1.join('\n').md5(),
                    pelines2.join('\n').md5()
                ).match() }
            )
        }
    }

    test("homo_sapiens paired-end [fastq] ribodetector") {

        when {
            workflow {
                """
                input[0] = CAT_FASTQ.out.reads                                    // ch_reads
                input[1] = []                                                     // ch_rrna_fastas (not needed for ribodetector)
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'ribodetector'                                         // ribo_removal_tool
                input[5] = false                                                  // make_sortmerna_index
                input[6] = false                                                  // make_bowtie2_index
                """
            }
        }

        then {
            def pelines1 = path(workflow.out.reads[0][1][0]).linesGzip
            def pelines2 = path(workflow.out.reads[0][1][1]).linesGzip

            // Parse ribodetector log for rRNA detection stats
            // Note: ribodetector log contains ANSI color codes that must be stripped before regex matching
            def ribodetectorLog = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.ribodetector.log') }?.getAt(1))
                .getText()
                .replaceAll(/\u001b\[[0-9;]*m/, '')  // Strip ANSI escape codes
            def ribodetectorRrnaMatch = (ribodetectorLog =~ /Detected (\d+) rRNA sequences/)
            def ribodetectorRrnaCount = ribodetectorRrnaMatch ? ribodetectorRrnaMatch[0][1].toInteger() : -1

            // Sort FASTQ reads before MD5 to handle ribodetector's non-deterministic output order
            // (multiprocessing causes variable read ordering even with --seed set)
            def sortedLines1 = pelines1.collate(4).sort { it[0] }.flatten()
            def sortedLines2 = pelines2.collate(4).sort { it[0] }.flatten()

            // Input: 4159 original + 10 synthetic rRNA = 4169 read pairs
            // RiboDetector removes 7 of 10 synthetic rRNA pairs (70% detection), leaving 4162 pairs
            assertAll(
                { assert workflow.success },
                { assert pelines1.size() == 16648 },  // 4162 pairs × 4 lines/read
                { assert pelines2.size() == 16648 },
                { assert ribodetectorRrnaCount == 7 },  // 7 pairs detected (70% - ML model misses some)
                { assert snapshot(
                    sortedLines1.join('\n').md5(),
                    sortedLines2.join('\n').md5()
                ).match() }
            )
        }
    }

    test("homo_sapiens paired-end [fastq] bowtie2") {

        when {
            workflow {
                """
                input[0] = CAT_FASTQ.out.reads                                    // ch_reads
                input[1] = Channel.of(file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/rfam-5.8s-database-id98.fasta', checkIfExists: true)) // ch_rrna_fastas
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'bowtie2'                                              // ribo_removal_tool
                input[5] = false                                                  // make_sortmerna_index
                input[6] = true                                                   // make_bowtie2_index
                """
            }
        }

        then {
            def pelines1 = path(workflow.out.reads[0][1][0]).linesGzip
            def pelines2 = path(workflow.out.reads[0][1][1]).linesGzip

            // Parse bowtie2 log for alignment stats - count mates that aligned to rRNA
            def bowtie2Log = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.bowtie2.log') }?.getAt(1))
                .getText()
            def exactMatch = (bowtie2Log =~ /(\d+) \(\d+\.\d+%\) aligned exactly 1 time/)
            def multiMatch = (bowtie2Log =~ /(\d+) \(\d+\.\d+%\) aligned >1 times/)
            def exactCount = exactMatch ? exactMatch[0][1].toInteger() : 0
            def multiCount = multiMatch ? multiMatch[0][1].toInteger() : 0
            def bowtie2RrnaCount = exactCount + multiCount

            // Input: 4159 original + 10 synthetic rRNA = 4169 read pairs
            // Bowtie2 aligns 17 individual mates to rRNA
            // Using samtools -f 12 keeps only pairs where BOTH mates are unmapped, leaving 4159 pairs
            assertAll(
                { assert workflow.success },
                { assert pelines1.size() == 16636 },  // 4159 pairs × 4 lines/read
                { assert pelines2.size() == 16636 },
                { assert bowtie2RrnaCount == 17 },  // 17 mates aligned to rRNA reference
                { assert snapshot(
                    pelines1.join('\n').md5(),
                    pelines2.join('\n').md5()
                ).match() }
            )
        }
    }

    test("homo_sapiens single-end [fastq] bowtie2") {

        setup {
            run("CAT_FASTQ", alias: "CAT_FASTQ_SE") {
                script "../../../../modules/nf-core/cat/fastq/main.nf"
                process {
                    """
                    // Single-end test data with synthetic rRNA reads
                    input[0] = Channel.of([
                        [ id:'test_se', single_end:true ],
                        [
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'generic/fastq/rrna_reads_1.fastq.gz', checkIfExists: true)
                        ]
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = CAT_FASTQ_SE.out.reads.map { meta, reads -> [meta, reads instanceof List ? reads : [reads]] }
                input[1] = Channel.of(file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/rfam-5.8s-database-id98.fasta', checkIfExists: true)) // ch_rrna_fastas
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'bowtie2'                                              // ribo_removal_tool
                input[5] = false                                                  // make_sortmerna_index
                input[6] = true                                                   // make_bowtie2_index
                """
            }
        }

        then {
            // For single-end, reads output is a single file, not a list
            def selines = path(workflow.out.reads[0][1]).linesGzip

            // Parse bowtie2 log for alignment stats
            def bowtie2Log = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.bowtie2.log') }?.getAt(1))
                .getText()
            def exactMatch = (bowtie2Log =~ /(\d+) \(\d+\.\d+%\) aligned exactly 1 time/)
            def multiMatch = (bowtie2Log =~ /(\d+) \(\d+\.\d+%\) aligned >1 times/)
            def exactCount = exactMatch ? exactMatch[0][1].toInteger() : 0
            def multiCount = multiMatch ? multiMatch[0][1].toInteger() : 0
            def bowtie2RrnaCount = exactCount + multiCount

            // Input: 4159 original reads + 10 synthetic rRNA = 4169 reads
            // Bowtie2 aligns 10 reads to rRNA
            // Using --un-gz outputs unmapped reads directly: 4159 reads remain
            assertAll(
                { assert workflow.success },
                { assert selines.size() == 16636 },  // 4159 reads × 4 lines/read
                { assert bowtie2RrnaCount == 10 },   // 10 reads aligned to rRNA reference
                { assert snapshot(
                    selines.join('\n').md5()
                ).match() }
            )
        }
    }

    test("homo_sapiens single-end [fastq] sortmerna") {

        setup {
            run("CAT_FASTQ", alias: "CAT_FASTQ_SE") {
                script "../../../../modules/nf-core/cat/fastq/main.nf"
                process {
                    """
                    // Single-end test data with synthetic rRNA reads
                    input[0] = Channel.of([
                        [ id:'test_se', single_end:true ],
                        [
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/fastq/test_rnaseq_1.fastq.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'generic/fastq/rrna_reads_1.fastq.gz', checkIfExists: true)
                        ]
                    ])
                    """
                }
            }
        }

        when {
            workflow {
                """
                input[0] = CAT_FASTQ_SE.out.reads.map { meta, reads -> [meta, reads instanceof List ? reads : [reads]] }
                input[1] = Channel.of(file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/rfam-5.8s-database-id98.fasta', checkIfExists: true)) // ch_rrna_fastas
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'sortmerna'                                            // ribo_removal_tool
                input[5] = true                                                   // make_sortmerna_index
                input[6] = false                                                  // make_bowtie2_index
                """
            }
        }

        then {
            // For single-end, reads output is a single file, not a list
            def selines = path(workflow.out.reads[0][1]).linesGzip

            // Parse sortmerna log for rRNA detection stats
            def sortmernaLog = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.sortmerna.log') }?.getAt(1))
                .getText()
            def sortmernaRrnaMatch = (sortmernaLog =~ /Total reads passing E-value threshold = (\d+)/)
            def sortmernaRrnaCount = sortmernaRrnaMatch ? sortmernaRrnaMatch[0][1].toInteger() : -1

            // Input: 4159 original reads + 10 synthetic rRNA = 4169 reads
            // SortMeRNA removes all 10 synthetic rRNA reads (100% detection), leaving 4159 reads
            assertAll(
                { assert workflow.success },
                { assert selines.size() == 16636 },  // 4159 reads × 4 lines/read
                { assert sortmernaRrnaCount == 10 },  // 10 reads detected (100% detection)
                { assert snapshot(
                    selines.join('\n').md5()
                ).match() }
            )
        }
    }

    test("homo_sapiens paired-end [fastq] bowtie2 with duplicate rrna databases") {

        when {
            workflow {
                """
                input[0] = CAT_FASTQ.out.reads                                    // ch_reads
                // Test with multiple rRNA databases that contain clustered sequences with
                // duplicate identifiers. SILVA databases use clustered sequences where the sequence ID
                // (the part before the first space) can be the same across different databases, causing
                // "Duplicate entry in sam header" errors when building Bowtie2 indexes. This test ensures
                // the SEQKIT_REPLACE preprocessing correctly prefixes sequence IDs with their source
                // filename to create unique identifiers while preserving all sequences.
                input[1] = Channel.of(
                    file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/silva-euk-18s-id95.fasta', checkIfExists: true),
                    file('https://raw.githubusercontent.com/biocore/sortmerna/v4.3.4/data/rRNA_databases/silva-euk-28s-id98.fasta', checkIfExists: true)
                )                                                                 // ch_rrna_fastas
                input[2] = []                                                     // ch_sortmerna_index
                input[3] = []                                                     // ch_bowtie2_index
                input[4] = 'bowtie2'                                              // ribo_removal_tool
                input[5] = false                                                  // make_sortmerna_index
                input[6] = true                                                   // make_bowtie2_index
                """
            }
        }

        then {
            def pelines1 = path(workflow.out.reads[0][1][0]).linesGzip
            def pelines2 = path(workflow.out.reads[0][1][1]).linesGzip

            // Parse bowtie2 log for alignment stats
            def bowtie2Log = path(workflow.out.multiqc_files.find { entry -> entry[1].toString().endsWith('.bowtie2.log') }?.getAt(1))
                .getText()

            // The key test: workflow should complete successfully without SAM header duplicate errors
            // even when the same rRNA databases are provided multiple times
            assertAll(
                { assert workflow.success },
                { assert pelines1.size() >= 0 },  // Should have some reads
                { assert pelines2.size() >= 0 },  // Should have some reads
